#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/text/localizable/localizable_property.hpp"
#include "gui_forms/control/shared_capabilities/shared_capabilities.hpp"
#include "gui_forms/types.hpp"
#include "gui_forms/layout/style/layout_style.hpp"

#include <cmath>
#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// TextBlock's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/text_block.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// The block's own font; empty takes the theme's field typography (resolved_font). Must be a valid font specification (std::invalid_argument).
template <typename Declaring>
struct TextBlockFontCapability {
    PropertyCell<std::optional<FontSpec>, TextBlockFontCapability<Declaring>> font{};

    static void assign(TextBlockFontCapability& capability, std::optional<FontSpec> incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.font), incoming);
        if (!capability.font.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.font));
    }
};

// CSS text-align; start and end follow the effective layout direction (std::invalid_argument outside the enumeration).
template <typename Declaring>
struct TextBlockTextAlignCapability {
    PropertyCell<TextAlignment, TextBlockTextAlignCapability<Declaring>> text_align{TextAlignment::start};

    static void assign(TextBlockTextAlignCapability& capability, TextAlignment incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.text_align), incoming);
        if (!capability.text_align.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.text_align));
    }
};

// CSS line-height as a length in logical pixels at text scale 1; empty is normal. A present value must be finite and positive (std::invalid_argument).
template <typename Declaring>
struct TextBlockLineHeightCapability {
    PropertyCell<std::optional<double>, TextBlockLineHeightCapability<Declaring>> line_height{};

    static void assign(TextBlockLineHeightCapability& capability, std::optional<double> incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.line_height), incoming);
        if (!capability.line_height.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.line_height));
    }
};

// TextAlignment as a property value; defined beside TextBlock's table.
template <>
struct PropertyValueTraits<TextAlignment> {
    static PropertyType type();
    static BindingValue to_binding(TextAlignment value);
    static TextAlignment from_binding(const BindingValue& value);
};

// Every TextBlock capability, in the order the declaring class takes them.
template <typename Declaring>
struct TextBlockCapabilities : public TextCapability<Declaring>,
                               public TextBlockFontCapability<Declaring>,
                               public TextBlockTextAlignCapability<Declaring>,
                               public TextBlockLineHeightCapability<Declaring> {};

} // namespace gui_forms
